{
  "name": "串口连接适配器",
  "name_en": "Serial Connection Adapter",
  "manufacturer": "",
  "description": "用于实验设备通信的非物理软件组件，通过串口建立与仪器的命令/响应通信。它负责打开和关闭串口、后台监听数据、发送消息并接收设备回复，供上层实验控制模块与串口仪器交互。",
  "description_en": "A non-physical software component used for laboratory device communication over a serial port. It opens and closes the serial connection, listens for incoming data in the background, transmits messages, and receives device replies for higher-level experiment control modules.",
  "actions": [
    {
      "action_name": "auto-open_connection",
      "description": "打开并初始化串口连接。",
      "description_en": "Open and initialize the serial connection."
    },
    {
      "action_name": "auto-connection_listener",
      "description": "后台监听串口数据并将收到的回复放入缓冲区。",
      "description_en": "Listen for serial data in the background and place received replies into the buffer."
    },
    {
      "action_name": "auto-close_connection",
      "description": "关闭串口连接并停止监听线程。",
      "description_en": "Close the serial connection and stop the listener thread."
    },
    {
      "action_name": "auto-is_connection_open",
      "description": "检查串口连接是否处于打开状态。",
      "description_en": "Check whether the serial connection is open."
    },
    {
      "action_name": "auto-transmit",
      "description": "通过串口发送消息到设备。",
      "description_en": "Transmit a message to the device over the serial connection."
    },
    {
      "action_name": "auto-receive",
      "description": "从接收缓冲区读取设备回复。",
      "description_en": "Receive a device reply from the receive buffer."
    }
  ],
  "tag_hints": [
    "serial communication",
    "instrument I/O",
    "COM port connection",
    "command-response messaging",
    "asynchronous listener thread",
    "lab device connectivity"
  ]
}

